"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createParts } from "@ui-sdk/react/primitive"
import { createToggleController, Toggle, type TogglePressedChangeReason } from "@ui-sdk/react/toggle"
import { useState, type ReactNode } from "react"

import { retroTv } from "@/components/ui/retro-tv-primitive"
import { ControlTooltip } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

const { Root: RetroTvRoot } = createParts(retroTv, { root: "div" })

type RetroTvPhosphor = "green" | "amber" | "white"

type RetroTvLabels = {
  /** Names the power button, a toggle pressed while the set is on. */
  power: string
}

const retroTvLabels: RetroTvLabels = { power: "Power" }

type RetroTvState = { power: boolean; disabled: boolean }

type RetroTvPowerChangeDetails = ChangeDetails<TogglePressedChangeReason>

type RetroTvProps = {
  /** The accessible name of the set, as a group. */
  label: string
  /** What the screen shows, in phosphor: text, stat cards, charts. It fills a 4:3 box sized by `--retro-tv-screen-width` and `--retro-tv-screen-height`. */
  children?: ReactNode
  /** Whether the set is on. Pass it to control the set. */
  power?: boolean
  /** Whether the set starts on, when uncontrolled. `true` by default. */
  defaultPower?: boolean
  /** Runs when the power button or an agent switches the set, with UI SDK's toggle details; `details.cancel()` keeps it as it is. */
  onPowerChange?: (power: boolean, details: RetroTvPowerChangeDetails) => void
  /** The colour of the phosphor: `green` by default, `amber` or `white`. */
  phosphor?: RetroTvPhosphor
  /** Turns the set a little in 3D; `false` shows it straight on. `true` by default. */
  perspective?: boolean
  disabled?: boolean
  labels?: Partial<RetroTvLabels>
  /** Classes for the root; a function gets the set's state. */
  className?: string | ((state: RetroTvState) => string | undefined)
}

/**
 * A 1980s tube TV with a wood cabinet: its screen shows any children in phosphor, behind curved glass with scanlines,
 * a vignette and a flickering glare. Its power button is UI SDK's toggle; switching off collapses the picture to a line,
 * then to a dot that fades, and switching on plays it back. Agents call `powerOn` and `powerOff`.
 */
function RetroTv({
  label,
  children,
  power,
  defaultPower = true,
  onPowerChange,
  phosphor = "green",
  perspective = true,
  disabled = false,
  labels: labelOverrides,
  className,
}: RetroTvProps) {
  const labels = { ...retroTvLabels, ...labelOverrides }
  const [toggle] = useState(createToggleController)
  const [ownPower, setOwnPower] = useState(defaultPower)
  const [switched, setSwitched] = useState(false)
  const on = power ?? ownPower
  const powerState = { "data-power": on ? "on" : "off", "data-switched": switched ? "" : undefined }

  const onPressedChange = (next: boolean, details: RetroTvPowerChangeDetails) => {
    onPowerChange?.(next, details)
    if (details.canceled) return
    setSwitched(true)
    setOwnPower(next)
  }

  return (
    <RetroTvRoot
      power={toggle}
      disabled={disabled}
      aria-label={label}
      data-phosphor={phosphor}
      data-perspective={perspective ? "" : undefined}
      {...powerState}
      className={cn(typeof className === "function" ? className({ power: on, disabled }) : className)}
    >
      <div data-slot="retro-tv-set">
        <div data-slot="retro-tv-cabinet">
          <div data-slot="retro-tv-bezel">
            <div data-slot="retro-tv-tube" {...powerState}>
              <div data-slot="retro-tv-picture" inert={!on} {...powerState}>
                {children}
              </div>
              <span data-slot="retro-tv-beam" aria-hidden="true" {...powerState} />
              <span data-slot="retro-tv-glass" aria-hidden="true" {...powerState} />
            </div>
          </div>
          <div data-slot="retro-tv-panel">
            <span data-slot="retro-tv-knob" aria-hidden="true" />
            <span data-slot="retro-tv-knob" aria-hidden="true" />
            <span data-slot="retro-tv-grille" aria-hidden="true" />
            <div data-slot="retro-tv-switch">
              <span data-slot="retro-tv-led" aria-hidden="true" {...powerState} />
              <ControlTooltip label={labels.power}>
                <Toggle
                  controller={toggle}
                  pressed={on}
                  onPressedChange={onPressedChange}
                  disabled={disabled}
                  aria-label={labels.power}
                  render={(part) => <button {...part} data-slot="retro-tv-power" className="touch-target" />}
                />
              </ControlTooltip>
            </div>
          </div>
        </div>
        <span data-slot="retro-tv-side" aria-hidden="true" />
        <span data-slot="retro-tv-feet" aria-hidden="true" />
      </div>
    </RetroTvRoot>
  )
}

export { RetroTv, retroTvLabels }
export type { RetroTvLabels, RetroTvPhosphor, RetroTvPowerChangeDetails, RetroTvProps, RetroTvState }

import { definePrimitive } from "@ui-sdk/core"
import type { ToggleController } from "@ui-sdk/core/toggle"

import { settled, unavailable } from "@/lib/action-refusal"

type RetroTvSwitch = Pick<ToggleController, "isPressed" | "setPressed">

type RetroTvOptions = {
  power?: RetroTvSwitch
  disabled?: boolean
}

function switchTo(options: RetroTvOptions, on: boolean, action: string, event: Event | undefined) {
  if (options.disabled) return unavailable(action, "isn't available while the set is disabled", { event })
  if (!options.power) return unavailable(action, "isn't available: the power button isn't ready", { event })
  if (options.power.isPressed() === on) return true
  return settled(options.power.setPressed(on, { reason: "imperative", event }), action, { event })
}

/** A retro TV's agent surface: the power button is UI SDK's toggle, pressed while the set is on. */
const retroTv = definePrimitive({
  name: "retro-tv",
  options: { power: "value", disabled: "value" },
  // Workaround: not `disabled`: the bridge would hide every action from a disabled part without saying why.
  state: (options: RetroTvOptions) => ({ inert: Boolean(options.disabled) }),
  sync: (options) => ({ inert: Boolean(options.disabled) }),
  api: (context) => ({
    /** Turns the set on; `true` when it already is. */
    powerOn(event?: Event) {
      return switchTo(context.options(), true, "powerOn", event)
    },
    /** Turns the set off, with the picture collapsing to a dot; `true` when it already is. */
    powerOff(event?: Event) {
      return switchTo(context.options(), false, "powerOff", event)
    },
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-disabled": state.inert ? "" : undefined }),
    }),
  }),
  agent: { actions: ["powerOn", "powerOff"] },
})

export { retroTv }
export type { RetroTvOptions, RetroTvSwitch }

"use client"

import { useState, type ReactNode } from "react"
import { createPortal } from "react-dom"

import type { RetroTvPhosphor } from "@/components/ui/retro-tv"
import { cn, cssVars } from "@/lib/utils"

const collapseMs = 520
const dotFadeMs = 900
const reducedFadeMs = 240

type TvPowerOffProps = {
  /** Plays the transition over the whole page while `true`, and keeps the screen black once it ends. */
  playing: boolean
  /** The colour of the last line and dot: `white` by default. */
  phosphor?: RetroTvPhosphor
  className?: string
}

/**
 * A tube TV switching off over the whole page: the picture closes to a bright line, the line to a dot, and the dot
 * fades on black. Under reduced motion the page fades to black. Rendered into `document.body`, above everything.
 */
function TvPowerOff({ playing, phosphor = "white", className }: TvPowerOffProps) {
  if (!playing || typeof document === "undefined") return null
  return createPortal(
    <div
      data-slot="tv-power-off"
      data-phosphor={phosphor}
      aria-hidden="true"
      className={cn(className)}
      style={cssVars({
        "--tv-power-off-collapse": `${String(collapseMs)}ms`,
        "--tv-power-off-dot": `${String(dotFadeMs)}ms`,
        "--tv-power-off-fade": `${String(reducedFadeMs)}ms`,
      })}
    >
      <span data-slot="tv-power-off-beam" />
      <span data-slot="tv-power-off-dot" />
    </div>,
    document.body,
  )
}

type TvPowerOffOptions = { phosphor?: RetroTvPhosphor }

type TvPowerOffControls = {
  /** Whether the transition is on the page. */
  playing: boolean
  /** Plays the transition; resolves once the screen is black, for navigating after, like on "log out". */
  powerOff: () => Promise<void>
  /** Takes the black screen away again, when the page stays. */
  reset: () => void
  /** Render it once, anywhere in the app. */
  overlay: ReactNode
}

const prefersReducedMotion = () =>
  typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches

/** The page-wide power-off: render `overlay`, then `await powerOff()` before navigating. */
function useTvPowerOff({ phosphor }: TvPowerOffOptions = {}): TvPowerOffControls {
  const [playing, setPlaying] = useState(false)
  const powerOff = () => {
    setPlaying(true)
    const durationMs = prefersReducedMotion() ? reducedFadeMs : collapseMs + dotFadeMs
    return new Promise<void>((done) => setTimeout(done, durationMs))
  }
  return {
    playing,
    powerOff,
    reset: () => setPlaying(false),
    overlay: <TvPowerOff playing={playing} phosphor={phosphor} />,
  }
}

export { TvPowerOff, useTvPowerOff }
export type { TvPowerOffControls, TvPowerOffOptions, TvPowerOffProps }
